export function MarkdownCopyButton({
  ariaLabel,
  className,
  copiedLabel,
  text,
}: {
  ariaLabel: string
  className?: string
  copiedLabel: string
  text: string
}) {
  const [status, setStatus] = React.useState<CopyStatus>("idle")
  const timeoutRef = React.useRef<number | null>(null)

  React.useEffect(
    () => () => {
      if (timeoutRef.current !== null) window.clearTimeout(timeoutRef.current)
    },
    []
  )

  const copy = () => {
    if (timeoutRef.current !== null) window.clearTimeout(timeoutRef.current)
    void navigator.clipboard?.writeText(text).then(() => {
      setStatus("copied")
      timeoutRef.current = window.setTimeout(() => {
        timeoutRef.current = null
        setStatus("idle")
      }, 1200)
    })
  }

  return (
    <Button
      aria-label={status === "copied" ? copiedLabel : ariaLabel}
      className={className}
      size="icon-sm"
      title={ariaLabel}
      type="button"
      variant="ghost"
      onClick={copy}
    >
      {status === "copied" ? <Check /> : <Copy />}
    </Button>
  )
}

export function sanitizeMarkdownUrl(value: string) {
  const trimmed = value.trim()
  if (!trimmed) return ""
  if (trimmed.startsWith("#") || trimmed.startsWith("/")) return trimmed

  try {
    const url = new URL(trimmed, "https://retab.local")
    if (
      url.protocol === "http:" ||
      url.protocol === "https:" ||
      url.protocol === "mailto:"
    ) {
      return trimmed
    }
  } catch {
    return ""
  }

  return ""
}

export function sanitizeMarkdownImageUrl(value: string) {
  const safeUrl = sanitizeMarkdownUrl(value)
  if (!safeUrl || safeUrl.startsWith("mailto:") || safeUrl.startsWith("#")) {
    return ""
  }
  return safeUrl
}

import { marked, type Token, type Tokens } from "marked"

import {
  clampMarkdownPageHeight,
  createEstimatedMarkdownBlock,
  MARKDOWN_DOCUMENT_TARGET_PAGE_HEIGHT,
  pageChromeHeight,
} from "./markdown-document-layout"
import { splitTextLines } from "./text-viewer-resource"

export type MarkdownDocumentBlockKind =
  | "blockquote"
  | "callout"
  | "code"
  | "heading"
  | "html"
  | "image"
  | "list"
  | "math"
  | "paragraph"
  | "rule"
  | "table"

export interface MarkdownDocumentBlock {
  blockEndLine: number
  blockStartLine: number
  estimatedHeight: number
  headingId: string | null
  id: string
  isHostile: boolean
  kind: MarkdownDocumentBlockKind
  markdown: string
}

export interface MarkdownDocumentPage {
  blocks: MarkdownDocumentBlock[]
  estimatedHeight: number
  id: string
  markdown: string
  pageEndLine: number
  pageNumber: number
  pageStartLine: number
}

export interface MarkdownDocument {
  blocks: MarkdownDocumentBlock[]
  headingIdsByLine: Map<number, string>
  lineCount: number
  pages: MarkdownDocumentPage[]
  text: string
  wordCount: number
}

export type MarkdownLineRange = {
  end: number
  start: number
}

type SourceToken = Token & {
  raw?: string
  text?: string
  tokens?: Token[]
}

type HeadingRegistry = Map<string, number>

export function createMarkdownDocument(text: string): MarkdownDocument {
  const normalizedText = text.length === 0 ? " " : text
  const headingRegistry: HeadingRegistry = new Map()
  const blocks = createMarkdownBlocks(normalizedText, headingRegistry)
  const pages = createMarkdownPages(blocks)
  const headingIdsByLine = new Map<number, string>()

  for (const block of blocks) {
    if (block.headingId) {
      headingIdsByLine.set(block.blockStartLine, block.headingId)
    }
  }

  return {
    blocks,
    headingIdsByLine,
    lineCount: splitTextLines(normalizedText).length,
    pages,
    text: normalizedText,
    wordCount: countWords(normalizedText),
  }
}

export function findMarkdownPageForLine(
  pages: readonly MarkdownDocumentPage[],
  sourceLine: number
) {
  return pages.find(
    (page) => sourceLine >= page.pageStartLine && sourceLine <= page.pageEndLine
  )
}

export function markdownPageIntersectsLineRange({
  page,
  range,
}: {
  page: MarkdownDocumentPage
  range: MarkdownLineRange | null
}) {
  if (!range) return false
  return page.pageStartLine <= range.end && page.pageEndLine >= range.start
}

export function serializeMarkdownTableForClipboard(markdown: string) {
  const tableToken = marked
    .lexer(markdown, { gfm: true })
    .find((token): token is Tokens.Table => token.type === "table")
  if (!tableToken) return markdown.trim()

  const header = tableToken.header.map((cell) => cell.text.trim())
  const rows = tableToken.rows.map((row) => row.map((cell) => cell.text.trim()))
  return [header, ...rows].map((row) => row.join("\t")).join("\n")
}

function createMarkdownBlocks(
  text: string,
  headingRegistry: HeadingRegistry
): MarkdownDocumentBlock[] {
  const frontmatter = extractYamlFrontmatter(text)
  const blocks: MarkdownDocumentBlock[] = []

  if (frontmatter) {
    const estimatedBlock = createEstimatedMarkdownBlock({
      kind: "code",
      markdown: frontmatter.renderMarkdown,
    })
    blocks.push({
      blockEndLine: frontmatter.endLine,
      blockStartLine: 1,
      estimatedHeight: estimatedBlock.estimatedHeight,
      headingId: null,
      id: "block-1-frontmatter",
      isHostile: estimatedBlock.isHostile,
      kind: "code",
      markdown: frontmatter.renderMarkdown,
    })
  }

  const markdownText = frontmatter
    ? text.slice(frontmatter.markdown.length)
    : text
  const baseLine = frontmatter ? frontmatter.endLine + 1 : 1
  const tokens = marked.lexer(markdownText, { gfm: true })
  let cursorLine = baseLine
  let previousTokenWasBlock = false

  for (const token of tokens as SourceToken[]) {
    if (token.type === "space") {
      const rawLineCount = countRawLines(token.raw ?? "\n")
      cursorLine += previousTokenWasBlock
        ? Math.max(0, rawLineCount - 1)
        : rawLineCount
      continue
    }

    const raw = token.raw ?? tokenText(token)
    const blockStartLine = cursorLine
    const blockEndLine = Math.max(
      blockStartLine,
      blockStartLine + countRawLines(raw) - 1
    )
    const kind = markdownBlockKind(token, raw)
    const headingId =
      token.type === "heading"
        ? createHeadingId((token as Tokens.Heading).text, headingRegistry)
        : null
    const markdown = raw.trimEnd() || " "
    const estimatedBlock = createEstimatedMarkdownBlock({ kind, markdown })

    blocks.push({
      blockEndLine,
      blockStartLine,
      estimatedHeight: estimatedBlock.estimatedHeight,
      headingId,
      id: `block-${blocks.length + 1}-${blockStartLine}`,
      isHostile: estimatedBlock.isHostile,
      kind,
      markdown,
    })

    cursorLine = blockEndLine + 1
    previousTokenWasBlock = true
  }

  if (blocks.length === 0) {
    blocks.push({
      blockEndLine: 1,
      blockStartLine: 1,
      estimatedHeight: 120,
      headingId: null,
      id: "block-1-empty",
      isHostile: false,
      kind: "paragraph",
      markdown: " ",
    })
  }

  return blocks
}

function createMarkdownPages(
  blocks: readonly MarkdownDocumentBlock[]
): MarkdownDocumentPage[] {
  const pages: MarkdownDocumentPage[] = []
  let currentBlocks: MarkdownDocumentBlock[] = []
  let currentHeight = pageChromeHeight()

  const flush = () => {
    if (currentBlocks.length === 0) return
    const markdown = currentBlocks.map((block) => block.markdown).join("\n\n")
    const pageStartLine = currentBlocks[0]!.blockStartLine
    const pageEndLine = currentBlocks[currentBlocks.length - 1]!.blockEndLine
    pages.push({
      blocks: currentBlocks,
      estimatedHeight: clampMarkdownPageHeight(currentHeight),
      id: `page-${pages.length + 1}-${pageStartLine}`,
      markdown,
      pageEndLine,
      pageNumber: pages.length + 1,
      pageStartLine,
    })
    currentBlocks = []
    currentHeight = pageChromeHeight()
  }

  for (let index = 0; index < blocks.length; index++) {
    const block = blocks[index]!
    const nextBlock = blocks[index + 1]
    const blockHeight = block.estimatedHeight

    if (block.isHostile) {
      flush()
      currentBlocks.push(block)
      currentHeight += blockHeight
      flush()
      continue
    }

    const shouldKeepHeadingWithNext =
      block.kind === "heading" &&
      nextBlock &&
      currentHeight + blockHeight + nextBlock.estimatedHeight <=
        MARKDOWN_DOCUMENT_TARGET_PAGE_HEIGHT

    if (
      currentBlocks.length > 0 &&
      !shouldKeepHeadingWithNext &&
      currentHeight + blockHeight > MARKDOWN_DOCUMENT_TARGET_PAGE_HEIGHT
    ) {
      flush()
    }

    currentBlocks.push(block)
    currentHeight += blockHeight

    if (
      currentHeight > MARKDOWN_DOCUMENT_TARGET_PAGE_HEIGHT &&
      isOversizedBlock(block)
    ) {
      flush()
    }
  }

  flush()
  return pages
}

function extractYamlFrontmatter(text: string) {
  const match = text.match(/^---(?:\r?\n)([\s\S]*?)(?:\r?\n)---(?:\r?\n|$)/)
  if (!match) return null

  const markdown = match[0]
  const inner = match[1] ?? ""
  return {
    endLine: countRawLines(markdown),
    markdown,
    renderMarkdown: ["```yaml", inner.trimEnd(), "```"].join("\n"),
  }
}

function markdownBlockKind(
  token: Token,
  raw: string
): MarkdownDocumentBlockKind {
  if (isDirectiveBlock(raw)) return "callout"
  if (isMathBlock(raw)) return "math"

  switch (token.type) {
    case "blockquote":
      return "blockquote"
    case "code":
      return "code"
    case "heading":
      return "heading"
    case "html":
      return "html"
    case "list":
      return "list"
    case "hr":
      return "rule"
    case "table":
      return "table"
    case "paragraph": {
      const paragraph = token as Tokens.Paragraph
      return paragraph.tokens?.length === 1 &&
        paragraph.tokens[0]?.type === "image"
        ? "image"
        : "paragraph"
    }
    default:
      return "paragraph"
  }
}

function isDirectiveBlock(raw: string) {
  return /^:::(?:note|info|tip|success|warning|caution|danger|error|failure)\b/im.test(
    raw.trimStart()
  )
}

function isMathBlock(raw: string) {
  return /^\$\$[\s\S]*\$\$\s*$/.test(raw.trim())
}

function isOversizedBlock(block: MarkdownDocumentBlock) {
  return block.estimatedHeight > MARKDOWN_DOCUMENT_TARGET_PAGE_HEIGHT * 0.8
}

function createHeadingId(text: string, registry: HeadingRegistry) {
  const base = slugifyHeading(text) || "section"
  const count = registry.get(base) ?? 0
  registry.set(base, count + 1)
  return count === 0 ? base : `${base}-${count}`
}

function slugifyHeading(text: string) {
  return text
    .toLowerCase()
    .replace(/<[^>]*>/g, "")
    .replace(/[^\p{Letter}\p{Number}\s-]/gu, "")
    .trim()
    .replace(/\s+/g, "-")
}

function countRawLines(raw: string) {
  return splitTextLines(raw.replace(/\r?\n$/, "")).length
}

function tokenText(token: SourceToken) {
  return typeof token.text === "string" ? token.text : (token.raw ?? "")
}

function countWords(text: string) {
  return text.trim().split(/\s+/).filter(Boolean).length
}

export interface MarkdownVirtualItem {
  bottom: number
  height: number
  index: number
  key: string
  top: number
}

export interface MarkdownVirtualGeometry {
  count: number
  heights: readonly number[]
  keys: readonly string[]
  offsets: readonly number[]
  totalHeight: number
}

export interface MarkdownScrollAnchor {
  index: number
  offsetWithinItem: number
}

export function createMarkdownVirtualGeometry({
  count,
  estimateHeight,
  getKey,
  measuredHeights,
}: {
  count: number
  estimateHeight: (index: number) => number
  getKey: (index: number) => string
  measuredHeights: ReadonlyMap<string, number>
}): MarkdownVirtualGeometry {
  const heights: number[] = []
  const keys: string[] = []
  const offsets = [0]

  for (let index = 0; index < count; index++) {
    const key = getKey(index)
    const height = resolveMarkdownItemHeight({
      estimateHeight,
      index,
      key,
      measuredHeights,
    })
    keys.push(key)
    heights.push(height)
    offsets.push(offsets[index]! + height)
  }

  return {
    count,
    heights,
    keys,
    offsets,
    totalHeight: offsets[count] ?? 0,
  }
}

export function getMarkdownVirtualItems({
  geometry,
  overscanPx,
  scrollTop,
  viewportHeight,
}: {
  geometry: MarkdownVirtualGeometry
  overscanPx: number
  scrollTop: number
  viewportHeight: number
}): {
  items: MarkdownVirtualItem[]
  totalHeight: number
} {
  if (geometry.count === 0) {
    return { items: [], totalHeight: 0 }
  }

  const items: MarkdownVirtualItem[] = []
  const viewportTop = Math.max(0, scrollTop - overscanPx)
  const viewportBottom = scrollTop + viewportHeight + overscanPx
  const startIndex = findFirstItemWithBottomAtOrAfter(
    geometry.offsets,
    viewportTop
  )
  const endIndex = findFirstItemWithTopAfter(geometry.offsets, viewportBottom)

  for (let index = startIndex; index < endIndex; index++) {
    const top = geometry.offsets[index]!
    const bottom = geometry.offsets[index + 1]!
    items.push({
      bottom,
      height: geometry.heights[index]!,
      index,
      key: geometry.keys[index]!,
      top,
    })
  }

  return { items, totalHeight: geometry.totalHeight }
}

export function getMarkdownScrollAnchor({
  geometry,
  scrollTop,
}: {
  geometry: MarkdownVirtualGeometry
  scrollTop: number
}): MarkdownScrollAnchor | null {
  if (geometry.count === 0) return null

  const index = Math.min(
    findFirstItemWithBottomAtOrAfter(geometry.offsets, scrollTop),
    geometry.count - 1
  )
  return {
    index,
    offsetWithinItem: Math.max(0, scrollTop - geometry.offsets[index]!),
  }
}

export function scrollTopForMarkdownAnchor({
  anchor,
  geometry,
}: {
  anchor: MarkdownScrollAnchor
  geometry: MarkdownVirtualGeometry
}) {
  if (geometry.count === 0) return 0

  const targetIndex = Math.min(Math.max(0, anchor.index), geometry.count - 1)
  const targetHeight = geometry.heights[targetIndex]!
  return Math.max(
    0,
    geometry.offsets[targetIndex]! +
      Math.min(anchor.offsetWithinItem, Math.max(0, targetHeight - 1))
  )
}

export function topForMarkdownIndex({
  geometry,
  index,
}: {
  geometry: MarkdownVirtualGeometry
  index: number
}) {
  if (geometry.count === 0) return 0

  const targetIndex = Math.min(Math.max(0, index), geometry.count - 1)
  return geometry.offsets[targetIndex]!
}

function resolveMarkdownItemHeight({
  estimateHeight,
  index,
  key,
  measuredHeights,
}: {
  estimateHeight: (index: number) => number
  index: number
  key: string
  measuredHeights: ReadonlyMap<string, number>
}) {
  return Math.max(1, measuredHeights.get(key) ?? estimateHeight(index))
}

function findFirstItemWithBottomAtOrAfter(
  offsets: readonly number[],
  target: number
) {
  let low = 0
  let high = Math.max(0, offsets.length - 1)

  while (low < high) {
    const middle = Math.floor((low + high) / 2)
    if (offsets[middle + 1]! >= target) {
      high = middle
    } else {
      low = middle + 1
    }
  }

  return low
}

function findFirstItemWithTopAfter(
  offsets: readonly number[],
  target: number
) {
  let low = 0
  let high = Math.max(0, offsets.length - 1)

  while (low < high) {
    const middle = Math.floor((low + high) / 2)
    if (offsets[middle]! > target) {
      high = middle
    } else {
      low = middle + 1
    }
  }

  return low
}
